!function(){const e=`\n    <div id="welcome-popup" class="welcome-popup">\n      <div class="popup-header">\n        <img src="${chrome.runtime.getURL("icons8-easy-100-bg.png")}" alt="Icon">\n        <h2 class="popup-title">Social Media Extension</h2>\n      </div>\n      <p class="popup-welcome">Welcome to Social Media Assistant!</p>\n      <p>We're here to enhance your online conversations.</p>\n      <ol>\n        <li>Start by typing your initial thoughts.</li>\n        <li>Use our AI to expand or refine your comment.</li>\n        <li>Customize suggestions to match your style.</li>\n      </ol>\n      <p>Ready to make your voice heard</p>\n      <div class="popup-actions">\n        <label>\n          <input type="checkbox" id="dont-show-again"> Don't show it again\n        </label>\n        <button id="got-it-btn">Got it</button>\n      </div>\n    </div>\n  `;document.body.insertAdjacentHTML("beforeend",'<div id="popup-overlay"></div>'+e);const o=document.getElementById("popup-overlay"),n=document.getElementById("welcome-popup"),t=document.getElementById("got-it-btn"),i=document.getElementById("dont-show-again");t.addEventListener("click",(()=>{n.style.display="none",o.style.display="none",i.checked&&chrome.storage.sync.set({dontShowWelcomePopup:!0})})),chrome.storage.sync.get("dontShowWelcomePopup",(e=>{e.dontShowWelcomePopup?(o.style.display="none",n.style.display="none"):(o.style.display="block",n.style.display="block")}))}();